{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Surveillance Data",
    "operation": "add",
    "widgets_json": {
      "case_escalation_form": {
        "name": "Case Escalation Form",
        "description": "Escalate a surveillance case to a reviewer.",
        "endpoint": "/case-escalation",
        "type": "table",
        "w": 20,
        "h": 10,
        "staleTime": 900000,
        "params": {
          "escalation": {
            "inputs": [
              {
                "case_id": {
                  "type": "text",
                  "label": "Case",
                  "default": "C-1042"
                },
                "due_date": {
                  "type": "date",
                  "label": "Due date",
                  "default": "$currentDate+2d"
                },
                "escalate": {
                  "type": "button",
                  "label": "Escalate"
                }
              }
            ]
          },
          "case_scope": {
            "type": "text",
            "label": "Case Scope",
            "default": "C-1042",
            "description": "Case intake filter."
          }
        }
      },
      "alert_metric": {
        "name": "Open Alerts",
        "description": "Open alert count.",
        "endpoint": "/alert-count",
        "type": "metric",
        "w": 5,
        "h": 4,
        "staleTime": 900000
      },
      "alert_queue": {
        "name": "Alert Queue",
        "description": "Open surveillance alerts.",
        "endpoint": "/alert-queue",
        "type": "table",
        "w": 20,
        "h": 9,
        "staleTime": 900000,
        "params": {
          "severity": {
            "type": "text",
            "label": "Severity",
            "options": [
              "High",
              "Medium",
              "Low"
            ],
            "default": "high"
          }
        },
        "columns": [
          {
            "field": "alert_id",
            "headerName": "Alert",
            "cellDataType": "text"
          },
          {
            "field": "desk",
            "headerName": "Desk",
            "cellDataType": "text"
          },
          {
            "field": "severity",
            "headerName": "Severity",
            "cellDataType": "text",
            "renderFn": "titleCase"
          },
          {
            "field": "age_days",
            "headerName": "Age (d)",
            "cellDataType": "number",
            "formatterFn": "int"
          }
        ]
      }
    }
  }
}

